{
 "info": {
  "title": "trimmed",
  "version": "1.0.0"
 },
 "openapi": "3.1.0",
 "paths": {
  "/v3/marketing/contacts": {
   "get": {
    "responses": {
     "200": {
      "content": {
       "application/json": {
        "schema": {
         "properties": {
          "_metadata": {
           "properties": {
            "self": {
             "type": "string"
            }
           },
           "type": "object"
          },
          "contact_count": {
           "type": "integer"
          },
          "result": {
           "items": {
            "properties": {
             "_metadata": {
              "type": "object"
             },
             "address_line_1": {
              "type": "string"
             },
             "address_line_2": {
              "type": "string"
             },
             "alternate_emails": {
              "type": "array"
             },
             "anonymous_id": {
              "type": "string"
             },
             "city": {
              "type": "string"
             },
             "country": {
              "type": "string"
             },
             "created_at": {
              "type": "string"
             },
             "custom_fields": {
              "type": "object"
             },
             "email": {
              "type": "string"
             },
             "external_id": {
              "type": "string"
             },
             "facebook": {
              "type": "string"
             },
             "first_name": {
              "type": "string"
             },
             "id": {
              "type": "string"
             },
             "last_name": {
              "type": "string"
             },
             "line": {
              "type": "string"
             },
             "list_ids": {
              "type": "array"
             },
             "phone_number": {
              "type": "string"
             },
             "phone_number_id": {
              "type": "string"
             },
             "postal_code": {
              "type": "string"
             },
             "segment_ids": {
              "type": "array"
             },
             "state_province_region": {
              "type": "string"
             },
             "unique_name": {
              "type": "string"
             },
             "updated_at": {
              "type": "string"
             },
             "whatsapp": {
              "type": "string"
             }
            },
            "required": [
             "created_at",
             "id",
             "list_ids",
             "segment_ids",
             "updated_at"
            ],
            "type": "object"
           },
           "type": "array"
          }
         },
         "type": "object"
        }
       }
      }
     }
    },
    "summary": "Get Sample Contacts\n\n**This endpoint will return up to 50 of the most recent contacts uploaded or attached to a list**. \n\nThis list will then be sorted by email address.\n\nThe full contact count is also returned.\n\nPlease note that pagination of the contacts has been deprecated.\n\nTwilio SendGrid recommends exporting your contacts regularly as a backup to avoid issues or lost data."
   }
  }
 }
}
